from typing import List


def create_largest_permutation(g_from: List[int], g_to: List[int]) -> List[int]:
    # the graph is connected, so any full traversal contains every node; the largest
    # permutation of those values puts them in descending order
    return sorted(set(g_from) | set(g_to), reverse=True)


if __name__ == "__main__":
    assert create_largest_permutation([4, 5, 1, 4, 3], [5, 1, 4, 3, 2]) == [5, 4, 3, 2, 1]
    assert create_largest_permutation([3, 3], [1, 2]) == [3, 2, 1]
    assert create_largest_permutation([1, 2, 3, 2, 1], [2, 3, 4, 4, 4]) == [4, 3, 2, 1]
    print("ok")
